-- «Alle Seiten bearbeiten» (#426): Die Rolle «Redaktion» entfällt, der Webmaster (#423) ersetzt sie. Eine Zeile in «bearbeiter» ohne objekt_id (alle Seiten) wird zur Vergabe der Vorgabe-Rolle «Webmaster» (person_plattform_rolle):
--   für eine Person direkt; für einen Tag (Team) für jedes Mitglied zum Zeitpunkt der Migration, denn eine Rolle lässt sich nur Personen geben. Wer später in das Team kommt, bekommt die Rolle nicht mehr von selbst.
-- Danach sind die Zeilen ohne objekt_id gelöscht und objekt_id ist Pflicht; Sonderrechte pro Seite bleiben unverändert.
-- Die Vorgabe «Webmaster» hat dieselben Rechte wie vorher die Zeile «alle Seiten» (Seiten bearbeiten, veröffentlichen, anlegen und löschen, Medien, Weiterleitungen, Vorlagen).
-- Rückweg (von Hand): siehe rueckweg/0101_bearbeiter_ohne_alle_seiten.sql
-- Fehlt einer Abteilung die Vorgabe «Webmaster» (sie wird mit 0100 für jede Abteilung angelegt), entsteht sie hier, damit keine Vergabe verloren geht
INSERT INTO "plattform_rolle" ("abteilung_id", "name", "schluessel") SELECT "id", 'Webmaster', 'webmaster' FROM "abteilung" a WHERE NOT EXISTS (SELECT 1 FROM "plattform_rolle" r WHERE r."abteilung_id" = a."id" AND r."schluessel" = 'webmaster') ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO "plattform_rolle_recht" ("rolle_id", "recht") SELECT r."id", v."recht" FROM "plattform_rolle" r CROSS JOIN (VALUES ('seiten.bearbeiten'), ('seiten.veroeffentlichen'), ('seiten.anlegen_loeschen'), ('medien.verwalten'), ('weiterleitungen.verwalten'), ('vorlagen.nutzen')) AS v("recht") WHERE r."schluessel" = 'webmaster' AND NOT EXISTS (SELECT 1 FROM "plattform_rolle_recht" x WHERE x."rolle_id" = r."id") ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO "person_plattform_rolle" ("user_id", "rolle_id") SELECT DISTINCT b."user_id", r."id" FROM "bearbeiter" b INNER JOIN "user" u ON u."id" = b."user_id" AND u."abteilung_id" = b."abteilung_id" INNER JOIN "plattform_rolle" r ON r."abteilung_id" = b."abteilung_id" AND r."schluessel" = 'webmaster' WHERE b."objekt_typ" = 'seite' AND b."objekt_id" IS NULL AND b."user_id" IS NOT NULL ON CONFLICT DO NOTHING;--> statement-breakpoint
INSERT INTO "person_plattform_rolle" ("user_id", "rolle_id") SELECT DISTINCT pt."user_id", r."id" FROM "bearbeiter" b INNER JOIN "tag" t ON t."id" = b."tag_id" AND t."abteilung_id" = b."abteilung_id" INNER JOIN "person_tag" pt ON pt."tag_id" = t."id" INNER JOIN "user" u ON u."id" = pt."user_id" AND u."abteilung_id" = b."abteilung_id" INNER JOIN "plattform_rolle" r ON r."abteilung_id" = b."abteilung_id" AND r."schluessel" = 'webmaster' WHERE b."objekt_typ" = 'seite' AND b."objekt_id" IS NULL AND b."tag_id" IS NOT NULL ON CONFLICT DO NOTHING;--> statement-breakpoint
DELETE FROM "bearbeiter" WHERE "objekt_id" IS NULL;--> statement-breakpoint
ALTER TABLE "bearbeiter" ALTER COLUMN "objekt_id" SET NOT NULL;
